mapper.select:
SELECT sub.event_id AS "eventId", STRING_AGG(sub.team_name, ', ' ORDER BY sub.team_name) AS "teamNames" FROM ( SELECT DISTINCT g.event_id AS event_id, t.name AS team_name FROM bs_game_player_stat s INNER JOIN bs_game g ON s.game_id = g.id INNER JOIN bs_event e ON g.event_id = e.id LEFT JOIN bs_team t ON t.id = s.team_id AND t.deleted_at IS NULL WHERE s.player_id = #{playerId} AND e.tenant_id = #{tenantId} AND g.deleted_at IS NULL AND e.deleted_at IS NULL
AND g.event_id IN
#{eid}
) sub GROUP BY sub.event_id

mapper.sql:
FROM bs_game_player_stat s
INNER JOIN bs_game g ON s.game_id = g.id
INNER JOIN bs_event e ON g.event_id = e.id
LEFT JOIN bs_team tm ON tm.id = s.team_id AND tm.deleted_at IS NULL
WHERE s.player_id = #{playerId}
  AND e.tenant_id = #{tenantId}
  AND g.deleted_at IS NULL
  AND e.deleted_at IS NULL
  AND COALESCE(g.include_stats_in_ranking, true) = true


AND g.event_id = #{eventId}
AND e.season = #{season}

FROM bs_game_player_stat s
INNER JOIN bs_game g ON s.game_id = g.id
INNER JOIN bs_event e ON g.event_id = e.id
LEFT JOIN bs_team tm ON tm.id = s.team_id AND tm.deleted_at IS NULL
WHERE s.player_id = #{playerId}
  AND e.tenant_id = #{tenantId}
  AND g.deleted_at IS NULL
  AND e.deleted_at IS NULL
  AND COALESCE(g.include_stats_in_ranking, true) = true

  AND s.is_pitcher = 1
  AND s.ip IS NOT NULL AND s.ip > 0
AND g.event_id = #{eventId}
AND e.season = #{season}
